    Error getError(int id) {
        if (id < 0 || id >= ERROR_MAX_ENTRY) {
            return errors[0];
        }
        return errors[id];
    }

    Error getErrorPlace(int id, int line, int col) {
        if (id < 0 || id >= ERROR_MAX_ENTRY) {
            return errors[0];
        }
        Error er = errors[id];
        er.place.line = line;
        er.place.col = col;
        return er;
    }
